"""Invoice totals."""
from src.utils.money import round_half_up
from src.rates import fetch_rate


def invoice_total(lines):
    return round(sum(line["unit_price"] * line["quantity"] for line in lines), 2)


def convert_total(lines, currency):
    return round_half_up(invoice_total(lines) * fetch_rate(currency))

